pub fn json_string(value: &str) -> String {
    let mut out = String::from("\"");
    for c in value.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c < ' ' => {
                out.push_str(&format!("\\u{:04x}", c as u32))
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn main() {
    assert_eq!(json_string("hi"), "\"hi\"", "case 1");
    assert_eq!(json_string(""), "\"\"", "case 2");
    assert_eq!(json_string("a\"b"), "\"a\\\"b\"", "case 3");
    assert_eq!(
        json_string(
            "a
b"
        ),
        "\"a\\nb\"",
        "case 4"
    );
    assert_eq!(json_string("🦀"), "\"🦀\"", "case 5");
    println!("worked example passed");
}

